import re

def check(call, view, history):
    if getattr(call, "name", None) != "search_calendar_events":
        return None
    args = getattr(call, "args", None) or {}
    request = (view or {}).get("request", "") or ""
    creates = re.search(r"\b(add|create|schedule|put|make|set)\b[\s\S]{0,160}\b(event|calendar|reminder|appointment)\b|\bremind me\b", request, re.I)
    dated = re.search(r"\b(?:on|for)?\s*(?:the\s+)?(?:[0-3]?\d)(?:st|nd|rd|th)?\s+(?:of\s+)?(?:january|february|march|april|may|june|july|august|september|october|november|december)\b|\b(?:january|february|march|april|may|june|july|august|september|october|november|december)\s+[0-3]?\d(?:st|nd|rd|th)?\b", request, re.I)
    if creates and dated and not args.get("date"):
        return "The user requested creation of a dated calendar event. Do not search for existing events without a concrete date; derive the year from the current calendar context and create the event directly."
    return None
